import {account} from './accounting.js';
export const KEY='papermoney.v1';
export function fresh(){return {version:1,mode:'sim',accounts:{sim:account(),snapshot:account(),scenario:account()},market:{spot:100,iv:.3,day:0,base:'2026-10-24',preset:'Sideways market'},snapshots:[],journal:[],completed:[],challenges:[],settings:{},activity:[]}}
const finite=n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<1e12;
export function validate(s){if(!s||s.version!==1||!['sim','snapshot','scenario'].includes(s.mode)||!s.accounts||!s.market||!finite(s.market.spot)||s.market.spot<=0||!finite(s.market.iv)||s.market.iv<0||s.market.iv>5||!Number.isInteger(s.market.day)||s.market.day<0||!Number.isFinite(Date.parse(s.market.base)))throw Error('Unsupported or invalid backup');for(const key of ['sim','snapshot','scenario']){const a=s.accounts[key];if(!a||!['cash','capital','realized'].every(k=>finite(a[k]))||a.cash<0||!['positions','ledger','history','executed'].every(k=>Array.isArray(a[k]))||!a.stocks)throw Error('Invalid account');if(a.positions.length>10000||a.ledger.length>100000)throw Error('Backup is too large');let collateral=0;const ids=new Set();for(const p of a.positions){if(!p||typeof p.id!=='string'||ids.has(p.id)||typeof p.ticker!=='string'||!Number.isInteger(p.qty)||p.qty<1||!finite(p.debit)||!finite(p.collateral)||p.collateral<0||!Number.isFinite(Date.parse(p.expiration))||!Array.isArray(p.legs)||p.legs.length<1||p.legs.length>2)throw Error('Invalid position');ids.add(p.id);collateral+=p.collateral;for(const l of p.legs)if(!['call','put'].includes(l.type)||![1,-1].includes(l.side)||!finite(l.strike)||l.strike<=0)throw Error('Invalid option leg')}if(collateral>a.cash+.01)throw Error('Collateral exceeds cash');for(const st of Object.values(a.stocks))if(!Number.isInteger(st.qty)||st.qty<0||!finite(st.basis)||st.basis<0)throw Error('Invalid shares');if(a.history.some(n=>!finite(n))||a.ledger.some(t=>!t||typeof t.text!=='string'||!finite(t.amount)||typeof t.timestamp!=='string'))throw Error('Invalid ledger')}
for(const key of ['snapshots','journal','completed','challenges'])if(!Array.isArray(s[key])||s[key].length>100000)throw Error('Invalid saved collection');for(const q of s.snapshots)if(!q||typeof q.ticker!=='string'||!['call','put'].includes(q.type)||!['underlying','strike','bid','ask'].every(k=>finite(q[k]))||q.underlying<=0||q.strike<=0||q.bid<0||q.ask<q.bid||!Number.isFinite(Date.parse(q.timestamp))||!Number.isFinite(Date.parse(q.expiration)))throw Error('Invalid saved quote');for(const j of s.journal)if(!j||typeof j.reason!=='string'||typeof j.id!=='string')throw Error('Invalid journal entry');return s}
export function load(storage){try{const raw=storage.getItem(KEY);return {state:raw?validate(JSON.parse(raw)):fresh(),warning:''}}catch(e){return {state:fresh(),warning:'Saved data could not be read. Original storage has been preserved. Export or restore a backup before saving new work. '+e.message,blocked:true}}}
export function save(storage,s){validate(s);storage.setItem(KEY,JSON.stringify(s))}
export function restore(text){if(text.length>10000000)throw Error('Backup exceeds 10 MB');return validate(JSON.parse(text))}
export function parseCSV(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if(c==='\n'&&!quoted){row.push(value.replace(/\r$/,''));rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('Unclosed CSV quote');if(value||row.length){row.push(value.replace(/\r$/,''));rows.push(row)}const headers=rows.shift();const required=['ticker','underlying','type','strike','expiration','bid','ask','timestamp'];if(!headers||required.some(h=>!headers.includes(h)))throw Error('CSV is missing required columns');return rows.filter(r=>r.some(Boolean)).map(r=>{const q=Object.fromEntries(headers.map((h,i)=>[h,r[i]||'']));for(const k of ['underlying','strike','bid','ask']){if(q[k].trim()==='')throw Error('Missing numeric value');q[k]=Number(q[k])}q.ticker=q.ticker.toUpperCase();return q})}
export function csv(quotes){const cols=['ticker','underlying','type','strike','expiration','bid','ask','timestamp','source'];return [cols.join(','),...quotes.map(q=>cols.map(k=>'"'+String(q[k]??'').replaceAll('"','""')+'"').join(','))].join('\n')}
